class HostApplication:          # e.g. a chat assistant
    def __init__(self):
        self.clients = {}       # one MCPClient per connected server

    def connect_server(self, name, server_url):
        self.clients[name] = MCPClient(server_url)

class MCPClient:                # lives inside the host
    def __init__(self, server_url):
        self.server_url = server_url

    def call_tool(self, name, args):
        # handles JSON-RPC details, talks to exactly one server
        return self._send_request("tools/call", {"name": name, "arguments": args})

# MCPServer is a separate process — could be Python, Node, Go, anything —
# as long as it correctly speaks the MCP protocol back to the client.
```
